/*
 * mmap/test/test_mmap_data.c - the MMAP module's data blocks
 *
 * Generated by: Claude Opus 5.5
 *
 * MMAP_$MMAPE (source-fyjc): the MMAP page table, map MMAP 0xEB4800 in
 * "D EB4800 OS_PMAPS size = 10000" up to MMU_$PTTX 0xEC2800 - 0xE00
 * mmape_t entries for ppn 0x200..0xFFF, the Pascal lower bound applied once
 * by MMAPE_FOR_VPN (entry ppn at the image's 0xEB2800 + ppn*0x10), page
 * aligned, zero-filled.  Also the MMAP_ block's image contents (MMAP_$DATA,
 * 0xE23284).
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

static int tests_passed = 0;
static int tests_failed = 0;

#define RUN_TEST(name) do { \
    printf("  Running %s... ", #name); \
    test_##name(); \
    printf("PASSED\n"); \
    tests_passed++; \
} while (0)

#define ASSERT_EQ(expected, actual) do { \
    if ((unsigned long)(expected) != (unsigned long)(actual)) { \
        printf("FAILED\n    Expected: 0x%lx, Got: 0x%lx at line %d\n", \
               (unsigned long)(expected), (unsigned long)(actual), __LINE__); \
        tests_failed++; \
        return; \
    } \
} while (0)

#include "mmap/mmap_internal.h"
#include "../mmap_data.c"

/* Lay the target VA space over the table at its image address. */
static void at_image_address(void)
{
    ARCH_HOST_VA_BASE = (uintptr_t)&MMAP_$MMAPE - 0x00EB4800u;
}

static void test_table_size_and_address(void)
{
    ASSERT_EQ(0xE000, sizeof(mmap_$mmape_table_t));
    ASSERT_EQ(MMAP_$MMAPE_SIZE, sizeof(MMAP_$MMAPE));
    ASSERT_EQ(0xE00, MMAP_MMAPE_COUNT);
    ASSERT_EQ(0x00EB4800u, MODULE_DATA_ADDR(MMAP_$MMAPE));
    /* the table ends where MMU_$PTTX begins */
    ASSERT_EQ(0x00EC2800u, MODULE_DATA_ADDR(MMAP_$MMAPE) + MMAP_$MMAPE_SIZE);
}

static void test_entry_stride(void)
{
    ASSERT_EQ(0x10, sizeof(mmape_t));
    ASSERT_EQ(0x10, (char *)MMAPE_FOR_VPN(0x201) - (char *)MMAPE_FOR_VPN(0x200));
    ASSERT_EQ(0x06, offsetof(mmape_t, prev_vpn));
    ASSERT_EQ(0x0A, offsetof(mmape_t, next_vpn));
    ASSERT_EQ(0x0C, offsetof(mmape_t, disk_addr));
}

/* MMAP_$LO_INDX / MMAP_$HI_INDX in the MMAP_ block are the table's bounds. */
static void test_bounds_are_the_blocks_indices(void)
{
    ASSERT_EQ(MMAP_MMAPE_FIRST_PPN, MMAP_$LO_INDX);
    ASSERT_EQ(MMAP_MMAPE_LAST_PPN, MMAP_$HI_INDX);
    ASSERT_EQ((uintptr_t)&MMAP_$MMAPE.entry[0],
              (uintptr_t)MMAPE_FOR_VPN(MMAP_MMAPE_FIRST_PPN));
    ASSERT_EQ((uintptr_t)&MMAP_$MMAPE.entry[MMAP_MMAPE_COUNT - 1],
              (uintptr_t)MMAPE_FOR_VPN(MMAP_MMAPE_LAST_PPN));
}

/* The bias: entry ppn is the image's 0xEB2800 + ppn*0x10, i.e. the
 * (-0x2000,An) displacement off 0xEB4800 + ppn*0x10 every user forms. */
static void test_bias_matches_the_image(void)
{
    at_image_address();
    ASSERT_EQ(0x00EB4800u, ARCH_PTR_TO_VA(MMAPE_FOR_VPN(0x200)));
    ASSERT_EQ(0x00EB2800u + 0x345u * 0x10u, ARCH_PTR_TO_VA(MMAPE_FOR_VPN(0x345)));
    ASSERT_EQ(0x00EC27F0u, ARCH_PTR_TO_VA(MMAPE_FOR_VPN(0xFFF)));
    /* netbuf's (-0x1ffa,A1) with A1 = 0xEB4800 + ppn*16: the +6 word */
    ASSERT_EQ(0x00EB4800u + 0x300u * 0x10u - 0x1FFAu,
              ARCH_PTR_TO_VA(&MMAPE_FOR_VPN(0x300)->prev_vpn));
    ARCH_HOST_VA_BASE = 0;
}

/* OS_$INIT frees the table's 56 pages by VA, MMAP_$INIT translates them:
 * 64 entries per 1 KB page, page-aligned type. */
static void test_pages(void)
{
    ASSERT_EQ(0x400, _Alignof(mmap_$mmape_table_t));
    ASSERT_EQ(56, sizeof(MMAP_$MMAPE) / 0x400);
    ASSERT_EQ(0x400, (char *)MMAPE_FOR_VPN(0x200 + 64) - (char *)MMAPE_FOR_VPN(0x200));
}

static void test_zero_filled(void)
{
    const uint8_t *p = (const uint8_t *)&MMAP_$MMAPE;
    size_t i;
    for (i = 0; i < sizeof(MMAP_$MMAPE); i++) {
        ASSERT_EQ(0, p[i]);
    }
}

/* MMAP_$DATA's non-zero image cells (mmap/mmap_data.c). */
static void test_mmap_block_contents(void)
{
    ASSERT_EQ(0x00000FFFu, MMAP_$HI_INDX);
    ASSERT_EQ(0x00000200u, MMAP_$LO_INDX);
    ASSERT_EQ(0x00000042u, MMAP_$MIN_RMT_POOL);
    ASSERT_EQ(0x00000001u, MMAP_$HPPN);
    ASSERT_EQ(0x00000FFFu, MMAP_$LPPN);
    ASSERT_EQ(0x0001, MMAP_$FORMAT);
    ASSERT_EQ(0x0008, MMAP_$WSL_HI_MARK);
}

int main(void)
{
    printf("MMAP data block tests:\n");
    RUN_TEST(table_size_and_address);
    RUN_TEST(entry_stride);
    RUN_TEST(bounds_are_the_blocks_indices);
    RUN_TEST(bias_matches_the_image);
    RUN_TEST(pages);
    RUN_TEST(zero_filled);
    RUN_TEST(mmap_block_contents);
    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed != 0;
}
